mapper.select:
SELECT * FROM ledger_transactions
WHERE card_id = #{cardId}
ORDER BY transaction_date DESC, id DESC

SELECT * FROM ledger_transactions
WHERE card_id = #{cardId}

    AND type = #{type}


    AND transaction_date >= #{fromDate}


    AND transaction_date <= #{toDate}


    AND is_void = #{isVoid}

ORDER BY transaction_date DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM ledger_transactions
WHERE card_id = #{cardId}
  AND is_void = FALSE
  AND transaction_date >= #{fromDate}
  AND transaction_date <= #{toDate}
ORDER BY transaction_date DESC, id DESC

SELECT COUNT(*) FROM ledger_transactions
WHERE card_id = #{cardId}

    AND type = #{type}


    AND transaction_date >= #{fromDate}


    AND transaction_date <= #{toDate}


    AND is_void = #{isVoid}

SELECT * FROM ledger_transactions
WHERE card_id = #{cardId}
  AND is_void = FALSE
ORDER BY transaction_date DESC, id DESC
LIMIT #{limit}

SELECT COALESCE(SUM(amount), 0)
FROM ledger_transactions
WHERE card_id = #{cardId}
  AND type = #{type}
  AND is_void = FALSE
  AND transaction_date >= #{startDate}
  AND transaction_date <= #{endDate}

SELECT COALESCE(SUM(amount), 0)
FROM ledger_transactions
WHERE card_id = #{cardId}
  AND direction = #{direction}
  AND is_void = FALSE
  AND transaction_date >= #{startDate}
  AND transaction_date <= #{endDate}

SELECT COALESCE(SUM(amount + CASE WHEN direction = 'OUT' THEN COALESCE(fee_amount, 0) ELSE 0 END), 0)
FROM ledger_transactions
WHERE card_id = #{cardId}
  AND direction = #{direction}
  AND is_void = FALSE
  AND transaction_date >= #{startDate}
  AND transaction_date <= #{endDate}

SELECT COALESCE(SUM(amount + COALESCE(fee_amount, 0)), 0)
FROM ledger_transactions
WHERE card_id = #{cardId}
  AND type IN ('ATM_WITHDRAWAL', 'ONLINE_PAYMENT', 'CARD_PAYMENT')
  AND direction = 'OUT'
  AND is_void = FALSE
  AND transaction_date >= #{startDate}
  AND transaction_date <= #{endDate}

mapper.delete:
DELETE FROM ledger_transactions
WHERE card_id = #{cardId}
  AND transaction_date >= #{fromDate}
  AND transaction_date <= #{toDate}
